"use strict";
import { useMemo } from "react";
export function useVeABXRewards(lock) {
  const rewardData = useMemo(() => {
    if (!lock) {
      return {
        rebaseAPR: "0",
        rebaseReward: "0",
        claimableRebase: "0",
        canClaimRebase: false,
        isLoading: false
      };
    }
    return {
      rebaseAPR: "N/A",
      // Will come from rebase distributor contract
      rebaseReward: "0",
      // Will be calculated based on voting power and rebase rate
      claimableRebase: "0",
      // Actual claimable rebase tokens
      canClaimRebase: false,
      // True when claimableRebase > 0
      isLoading: false
    };
  }, [lock]);
  const claimRebase = async () => {
    if (!lock) {
      throw new Error("No lock provided");
    }
    console.log("Claiming rebase rewards for lock:", lock.id);
    throw new Error("Rebase claiming not yet implemented - contracts not deployed");
  };
  return {
    ...rewardData,
    claimRebase
  };
}
export function useGlobalRebaseInfo() {
  return useMemo(() => {
    return {
      currentRebaseRate: "0",
      // Current rebase rate percentage
      totalRebaseDistributed: "0",
      // Total ABX distributed as rebase
      nextRebaseTime: null,
      // Timestamp of next rebase epoch
      rebaseFrequency: "weekly",
      // How often rebase occurs
      isLoading: false
    };
  }, []);
}
