"use strict";
import { useGaugeStaking } from "hooks/useGaugeStaking";
import { Flex, Text, useSporeColors } from "ui/src";
import { CheckCircleFilled } from "ui/src/components/icons/CheckCircleFilled";
import { MinusCircle } from "ui/src/components/icons/MinusCircle";
import { PaperStack } from "ui/src/components/icons/PaperStack";
export function StakedStatusBadge({ position, hasGauge, size = "small" }) {
  const { isStaked: contractIsStaked, isLoading } = useGaugeStaking(position);
  const colors = useSporeColors();
  if (!hasGauge || isLoading) {
    return null;
  }
  const isPartiallyStaked = position.isPartiallyStaked;
  const isStaked = position.isStaked ?? contractIsStaked;
  const iconSize = size === "small" ? 12 : 14;
  const fontSize = size === "small" ? "buttonLabel4" : "buttonLabel4";
  if (isPartiallyStaked) {
    const percentage = position.stakingPercentage || 0;
    return <Flex
      row
      gap="$gap4"
      alignItems="center"
      px="$padding6"
      py="$padding2"
      borderRadius="$rounded8"
      backgroundColor="$accent2"
    >
        <PaperStack size={iconSize} color="$neutral2Temp" />
        <Text variant={fontSize} color="$neutral2Temp">
          {percentage}% Staked
        </Text>
      </Flex>;
  }
  return <Flex
    row
    gap="$gap4"
    alignItems="center"
    px="$spacing4"
    py="$spacing2"
    borderRadius="$rounded6"
    borderWidth={1}
    borderColor={isStaked ? "$absGreen" : "$surface3"}
    backgroundColor={isStaked ? "$statusSuccess2" : "$surface2"}
  >
      {isStaked ? <>
          <CheckCircleFilled size={iconSize} color="$statusSuccess" />
          <Text variant={fontSize} color="$statusSuccess">
            Staked
          </Text>
        </> : <>
          <MinusCircle size={iconSize} color={colors.neutral2.val} />
          <Text variant={fontSize} color="$neutral2">
            Unstaked
          </Text>
        </>}
    </Flex>;
}
