"use strict";
import { useCallback, useState } from "react";
import { errorToString } from "utilities/src/errors";
import { useVoterContract } from "./useVoterContract";
import {
  useVotingRewardsFromSubgraph,
  groupRewardsByType,
  getUniqueRewardContracts
} from "./useVotingRewardsFromSubgraph";
export function useClaimAndLock(lock) {
  const [state, setState] = useState({
    isLoading: false,
    isConfirming: false,
    isSuccess: false,
    error: null
  });
  const { claimFees, claimBribes, transactionState } = useVoterContract();
  const { rewards, canClaim } = useVotingRewardsFromSubgraph(lock);
  const { fees, bribes } = groupRewardsByType(rewards);
  const claimableContracts = getUniqueRewardContracts(rewards);
  const claimAndLock = useCallback(async () => {
    if (!lock) {
      console.error("No lock selected");
      return;
    }
    if (!canClaim) {
      console.warn("No rewards to claim");
      return;
    }
    setState({
      isLoading: true,
      isConfirming: false,
      isSuccess: false,
      error: null
    });
    try {
      const feeTokens = fees.map((f) => f.token.address);
      const bribeTokens = bribes.map((b) => b.token.address);
      if (claimableContracts.feeContracts.length > 0) {
        console.log("Claiming trading fees...");
        await claimFees(
          lock.id,
          claimableContracts.feeContracts,
          [feeTokens]
          // Array of token arrays for each contract
        );
        console.log("Trading fees claimed!");
      }
      if (claimableContracts.bribeContracts.length > 0) {
        console.log("Claiming bribe rewards...");
        await claimBribes(
          lock.id,
          claimableContracts.bribeContracts,
          [bribeTokens]
          // Array of token arrays for each contract
        );
        console.log("Bribe rewards claimed!");
      }
      console.log(`Rewards claimed for Lock #${lock.id.slice(-6)}!`);
      setState({
        isLoading: false,
        isConfirming: false,
        isSuccess: true,
        error: null
      });
    } catch (error) {
      console.error("Claim and lock failed:", error);
      const errorMessage = errorToString(error) || "Failed to claim rewards";
      console.error(errorMessage);
      setState({
        isLoading: false,
        isConfirming: false,
        isSuccess: false,
        error: errorMessage
      });
    }
  }, [lock, canClaim, fees, bribes, claimableContracts, claimFees, claimBribes]);
  const claimOnly = useCallback(async () => {
    if (!lock || !canClaim) return;
    setState({ isLoading: true, isConfirming: false, isSuccess: false, error: null });
    try {
      const feeTokens = fees.map((f) => f.token.address);
      const bribeTokens = bribes.map((b) => b.token.address);
      if (claimableContracts.feeContracts.length > 0) {
        await claimFees(lock.id, claimableContracts.feeContracts, [feeTokens]);
      }
      if (claimableContracts.bribeContracts.length > 0) {
        await claimBribes(lock.id, claimableContracts.bribeContracts, [bribeTokens]);
      }
      console.log("Rewards claimed successfully!");
      setState({ isLoading: false, isConfirming: false, isSuccess: true, error: null });
    } catch (error) {
      const errorMessage = errorToString(error) || "Failed to claim rewards";
      console.error(errorMessage);
      setState({ isLoading: false, isConfirming: false, isSuccess: false, error: errorMessage });
    }
  }, [lock, canClaim, fees, bribes, claimableContracts, claimFees, claimBribes]);
  const isActuallyLoading = state.isLoading || transactionState.isLoading;
  const isActuallyConfirming = state.isConfirming || transactionState.isConfirming;
  return {
    // Actions
    claimAndLock,
    claimOnly,
    // State
    isLoading: isActuallyLoading,
    isConfirming: isActuallyConfirming,
    isSuccess: state.isSuccess || transactionState.isSuccess,
    error: state.error || transactionState.error,
    canClaim,
    // Reward data
    fees,
    bribes,
    totalRewards: fees.length + bribes.length
  };
}
